-- Batch update 300k NULL customer_ids from legacy_customer_map in 60 batches of 5000
SELECT 'UPDATE orders SET customer_id = lcm.customer_id FROM legacy_customer_map lcm WHERE orders.id = lcm.order_id AND orders.customer_id IS NULL AND lcm.order_id IN (SELECT order_id FROM legacy_customer_map ORDER BY order_id LIMIT 5000 OFFSET ' || (gs * 5000) || ');'
FROM generate_series(0, 59) gs \gexec

-- Make customer_id NOT NULL (requires AccessExclusiveLock, brief table scan)
ALTER TABLE orders ALTER COLUMN customer_id SET NOT NULL;

-- Add foreign key NOT VALID (requires AccessExclusiveLock, brief)
ALTER TABLE orders ADD CONSTRAINT fk_orders_customer_id FOREIGN KEY (customer_id) REFERENCES customers(id) NOT VALID;

-- Validate foreign key (requires ShareUpdateExclusiveLock, compatible with readers/writers)
ALTER TABLE orders VALIDATE CONSTRAINT fk_orders_customer_id;

